\caption{Two-Set Policy}
\label{alg:two-set}
\hspace*{\algorithmicindent} \textbf{Input}: number of arms $N$, budget $\alpha N$, an optimal solution of LP-relaxation $y^*$, \\
\hspace*{\algorithmicindent} \hspace{0.37in} initial system state $X_0$, initial state vector $\ve{S}_0$, initial focus set $D_{-1}=\emptyset$, \\
\hspace*{\algorithmicindent} \hspace{0.37in} a feasibility-ensuring pair of ($\eta$, $\epsilon_N^{\text{fe}}$), error tolerance for subproblems $\epsilon_N^{\text{rd}} = O(1/N)$
\begin{algorithmic}[1]
    \For{$t=0,1,\dots$}
        \If{$\delta(X_t, [N]) \geq 0$} 
        \label{alg:two-set:update-db-step-begin}
            \State Let $D^{\textup{OL}}_t = [N]$
        \ElsIf{$\delta(X_t, D^{\textup{OL}}_{t-1}) \geq 0$} 
            \State Let $D^{\textup{OL}}_t$ be any $\epsilon_N^{\text{rd}}$-maximal feasible subset such that $D^{\textup{OL}}_t \supseteq D^{\textup{OL}}_{t-1}$. 
        \Else
            \State Let $D^{\textup{OL}}_t$ be any $\epsilon_N^{\text{rd}}$-maximal feasible subset. 
        \label{alg:two-set:update-db-step-end}
        \EndIf
        \State Let $D^{{{\sysbar{\pi}}^*}}_{t}$ be s.t. $D^{{{\sysbar{\pi}}^*}}_{t-1} \backslash D^{\textup{OL}}_{t} \subseteq D^{{{\sysbar{\pi}}^*}}_{t} \subseteq [N] \backslash D^{\textup{OL}}_t$ and $|D^{{{\sysbar{\pi}}^*}}_{t}| = \big\lfloor \beta (N -|D^{\textup{OL}}_{t}|)\big\rfloor$. 
        \State Set $A_t(i)$ for $i\in D^{\textup{OL}}_{t}$ using \Cref{alg:follow-lp-priority} Optimal Local Control. 
        \label{alg:two-set:db-action}
        \State Set $A_t(i)$ for $i\in D^{{{\sysbar{\pi}}^*}}_{t}$ using \Cref{alg:follow-pibs} Unconstrained Optimal Control. 
        \label{alg:two-set:da-action}
        \State Set $A_t(i)$ for $i\notin D^{\textup{OL}}_{t} \cup D^{{{\sysbar{\pi}}^*}}_{t}$ such that $\sum_{i\in[N]} A_t(i) = \alpha N$. 
        \label{alg:two-set:remaining-action}
        \State Apply $A_t(i)$ for $i\in[N]$ and observe the new state vector $\ve{S}_{t+1}$. 
    \EndFor
\end{algorithmic}

