\label{def:regular-unstable}
For an RB instance satisfying \Cref{assump:aperiodic-unichain} and \Cref{assump:non-degeneracy}, we call it regular unstable if it has the following properties: 
\begin{enumerate}[leftmargin=2em, label=(\alph*)]
    \item \label{assump:unique-and-communicating}
    \eqref{eq:lp-single} has a unique optimal solution $y^*$, and $y^*(s,1) + y^*(s,0) > 0$ for all $s\in\mathbb{S}$. 
    \item \label{assump:instability}
    The matrix $\Phi$ defined in \eqref{eq:phi-def} has at least one eigenvalue whose modulus is strictly larger than $1$, and the modulus of any eigenvalue of $\Phi$ does not equal $1$. 
    \item \label{assump:orthogonal-noise}
    For each $\xi \in \mathbb{R}^{|\mathbb{S}|}$ with $\normplain{\xi}_2 = 1$ and $\mu^* \xi^\top = 0$, for each large-enough $N$  and each time step $t$, 
    \begin{equation*}
        \Ebig{\absbig{\big(X_{t+1}([N]) - \mu^* - (X_t([N]) - \mu^*)\Phi \big)  \xi^\top } \,\big|\, X_t, \ve{A}_t} \geq \frac{K_{\textup{noise}}}{\sqrt{N}} \quad \text{ if } \norm{X_t([N]) - \mu^*}_1 \leq \eta',
    \end{equation*}
    where $\eta', K_{\textup{noise}} > 0$ are some constants; $\ve{A}_t$ follows the Optimal Local Control (\Cref{alg:follow-lp-priority}), which is always feasible if $\norm{X_t([N]) - \mu^*}_1 \leq \min\{y^*(\tilde{s}, 0), y^*(\tilde{s}, 1)\}-1/N$. 
    \end{enumerate}

