        \Ebig{V(\Sigma_{t+1}) - V(\Sigma_t) \,\big|\, \Sigma_t} &\leq -\gamma \\
        \label{eq:two-set:drift-lem:jump-1}
         \Ebig{(V(\Sigma_{t+1}) - V(\Sigma_t))^+  \,\big|\, \Sigma_t} &= O(1/\sqrt{N});
    \end{align}

\begin{equation}
        \label{eq:two-set:drift-lem:jump-2}
        \Ebig{(V(\Sigma_{t+1}) - V(\Sigma_t))^+  \,\big|\, \Sigma_t} = O(\exp(-C N)); 
    \end{equation}

\begin{equation}
        \label{eq:two-set:drift-lem:jump-3}
        \Probbig{V(\Sigma_{t+1}) > \overline{\eta}/2  \,\big|\, \Sigma_t} = O(\exp(-C' N)), 
    \end{equation}

\begin{align}
        \label{eq:two-set:drift-lem:conclusion}
        \Prob{V(\Sigma_{\infty}) > \overline{\eta}} = O(\exp(-C'' N)),   
    \end{align}

define two classes of functions, $h_W=\{h_W(x, D)\}_{D\subseteq [N]}$ and $h_U=\{h_U(x, D)\}_{D\subseteq [N]}$: 
For any system state $x$ and subset $D\subseteq[N]$, define
\begin{align}
    \label{eq:hw-def}
    h_W(x, D) &= \norm{x(D) - m(D)\mu^*}_W \\
    \label{eq:hu-def}
    h_U(x, D) &= \norm{x(D) - m(D)\mu^*}_U.

\begin{align}
    \label{eq:hw-def}
    h_W(x, D) &= \norm{x(D) - m(D)\mu^*}_W \\
    \label{eq:hu-def}
    h_U(x, D) &= \norm{x(D) - m(D)\mu^*}_U.
\end{align}

\label{lem:hw-hu-properties}
    Assume Assumptions~\ref{assump:aperiodic-unichain}, \ref{assump:non-degeneracy} and \ref{assump:local-stability} hold. 
    For any time step $t$ and $D\subseteq [N]$, let $X_{t+1}'$ be the system state at time $t+1$ if the arms in $D$ follow the Unconstrained Optimal Control at time $t$, then we have
    \begin{align}
        \label{eq:hw:drift}
        \Ebig{(h_W(X_{t+1}', D) - \rho_{w} h_W(X_t, D))^+ \,\big|\, X_t} &= O(1/\sqrt{N}) \quad a.s. \\
        \label{eq:hw:high-prob}
        \Probbig{h_W(X_{t+1}', D) > \rho_{w} h_W(X_t, D) + r   \,\big|\, X_t} &= O(\exp(-C N r^2)) \quad a.s. \quad \forall r \geq 0,
    \end{align}
    where $\rho_{w} = 1 - 1/(2\lambda_W)$, and $C$ is a positive constant. 
    In addition, for any $D, D'\subseteq [N]$, 
    \begin{align}
        \label{eq:hw:strength}
        h_W(x, D) &\geq \frac{1}{|\mathbb{S}|^{1/2}} \norm{x(D) - m(D)\mu^*}_1 \\
        \label{eq:hw:lipschitz}
        \abs{h_W(x, D) - h_W(x, D')} &\leq 2\lambda_W^{1/2} (m(D'\backslash D) + m(D\backslash D')),
    \end{align}
    The same inequalities hold for $h_U$ with the Unconstrained Optimal Control and $W$ replaced by the Optimal Local Control and $U$. We omit the details here.

\begin{align}
        \label{eq:hw:drift}
        \Ebig{(h_W(X_{t+1}', D) - \rho_{w} h_W(X_t, D))^+ \,\big|\, X_t} &= O(1/\sqrt{N}) \quad a.s. \\
        \label{eq:hw:high-prob}
        \Probbig{h_W(X_{t+1}', D) > \rho_{w} h_W(X_t, D) + r   \,\big|\, X_t} &= O(\exp(-C N r^2)) \quad a.s. \quad \forall r \geq 0,
    \end{align}

\begin{align}
        \label{eq:hw:strength}
        h_W(x, D) &\geq \frac{1}{|\mathbb{S}|^{1/2}} \norm{x(D) - m(D)\mu^*}_1 \\
        \label{eq:hw:lipschitz}
        \abs{h_W(x, D) - h_W(x, D')} &\leq 2\lambda_W^{1/2} (m(D'\backslash D) + m(D\backslash D')),
    \end{align}

\label{lem:two-set:non-shrink}
    Assume Assumptions~\ref{assump:aperiodic-unichain}, \ref{assump:non-degeneracy} and \ref{assump:local-stability} hold. 
    Consider the two-set policy (\Cref{alg:two-set}) such that $(\eta, \epsilon_N^{\text{fe}})$ is feasibility-ensuring, $\eta=\Theta(1)$ and $\epsilon_N^{\text{fe}}=O(1/N)$. 
    For any $t\geq0$, we have
    \begin{align}
        \label{eq:two-set:non-shrink-drift}
        \Ebig{m(D^{\textup{OL}}_t\backslash D^{\textup{OL}}_{t+1}) \,\big|\, \Sigma_t} &= O(m(D^{\textup{OL}}_t)\exp(-C N m(D^{\textup{OL}}_t)^2)) \quad a.s. \\
        \label{eq:two-set:non-shrink-high-prob}
        \Probbig{m(D^{\textup{OL}}_{t}\backslash D^{\textup{OL}}_{t+1}) > 0 \,\big|\, \Sigma_t} &= O(\exp(-C N m(D^{\textup{OL}}_t)^2)) \quad a.s.,
    \end{align}
    where $C$ is a positive constant.

\begin{align}
        \label{eq:two-set:non-shrink-drift}
        \Ebig{m(D^{\textup{OL}}_t\backslash D^{\textup{OL}}_{t+1}) \,\big|\, \Sigma_t} &= O(m(D^{\textup{OL}}_t)\exp(-C N m(D^{\textup{OL}}_t)^2)) \quad a.s. \\
        \label{eq:two-set:non-shrink-high-prob}
        \Probbig{m(D^{\textup{OL}}_{t}\backslash D^{\textup{OL}}_{t+1}) > 0 \,\big|\, \Sigma_t} &= O(\exp(-C N m(D^{\textup{OL}}_t)^2)) \quad a.s.,
    \end{align}

\label{lem:two-set:sufficient-coverage}
    Assume Assumptions~\ref{assump:aperiodic-unichain}, \ref{assump:non-degeneracy} and \ref{assump:local-stability} hold. 
    Consider the two-set policy (\Cref{alg:two-set}) such that $(\eta, \epsilon_N^{\text{fe}})$ is feasibility-ensuring, $\eta=\Theta(1)$ and $\epsilon_N^{\text{fe}}=O(1/N)$. 
    For any $t\geq0$, we have
    \begin{align}
        \label{eq:two-set:sufficient-coverage:goal-1}
        1-m(D^{\textup{OL}}_t) &\leq  \frac{\lambda_U^{1/2}}{\eta\beta}  h_W(X_t, D^{{{\sysbar{\pi}}^*}}_t) + \frac{1}{\beta N} + \frac{\epsilon_N^{\text{rd}}+\epsilon_N^{\text{fe}}}{\min(\eta, 1)\beta} \quad a.s.\\
        \label{eq:two-set:sufficient-coverage:goal-2}
        m(D^{\textup{OL}}_t) &= 1 \quad \text{ if } h_U(X_t, [N]) \leq \eta. 
    \end{align}

\begin{align}
        \label{eq:two-set:sufficient-coverage:goal-1}
        1-m(D^{\textup{OL}}_t) &\leq  \frac{\lambda_U^{1/2}}{\eta\beta}  h_W(X_t, D^{{{\sysbar{\pi}}^*}}_t) + \frac{1}{\beta N} + \frac{\epsilon_N^{\text{rd}}+\epsilon_N^{\text{fe}}}{\min(\eta, 1)\beta} \quad a.s.\\
        \label{eq:two-set:sufficient-coverage:goal-2}
        m(D^{\textup{OL}}_t) &= 1 \quad \text{ if } h_U(X_t, [N]) \leq \eta. 
    \end{align}

Define the Lyapunov function $V(x, D^{\textup{OL}}, D^{{{\sysbar{\pi}}^*}})$ as
\begin{equation}\label{eq:two-set:full-lyapunov}
    V(x, D^{\textup{OL}}, D^{{{\sysbar{\pi}}^*}}) = h_U(x, D^{\textup{OL}}) + h_W(x, D^{{{\sysbar{\pi}}^*}}) + L (1 - m(D^{\textup{OL}})),
\end{equation}
where $L = 2\lambda_U^{1/2} + 4\lambda_W^{1/2} - 2\lambda_W^{1/2}\beta$. 
We claim that
\begin{equation}
    \label{eq:two-set:thm:interm-goal-1}
    \Probbig{V(X_\infty, D^{\textup{OL}}_\infty, D^{{{\sysbar{\pi}}^*}}_\infty) > \eta - \epsilon_N^{\text{fe}}} = O(\exp(-CN)),
\end{equation}
for some positive constant $C$. 
To see why \eqref{eq:two-set:thm:interm-goal-1} helps, note that by \Cref{lem:hw-hu-properties}, 
\[
    V(x, D^{\textup{OL}}, D^{{{\sysbar{\pi}}^*}}) \geq  h_U(x, D^{\textup{OL}}) + 2\lambda_U^{1/2} (1 - m(D^{\textup{OL}})) \geq h_U(x, [N]),
\]
so $V(X_\infty, D^{\textup{OL}}_\infty, D^{{{\sysbar{\pi}}^*}}_\infty) \leq \eta - \epsilon_N^{\text{fe}}$ implies $h_U(X_\infty, [N]) \leq \eta - \epsilon_N^{\text{fe}}$, which further implies $D^{\textup{OL}}_\infty =[N]$ by \Cref{lem:two-set:sufficient-coverage}. Therefore, suppose we get \eqref{eq:two-set:thm:interm-goal-1}, with \Cref{lem:two-set:opt-gap-bound-by-prob} and the above argument, we have
\begin{align*}
    R^{\textup{rel}} - R(\pi, \ve{S}_0)     
    &\leq O(1)\cdot \Probbig{D^{\textup{OL}}_\infty \neq [N]} \\
    &\leq O(1)\cdot \Probbig{h_U(X_\infty, [N]) > \eta - \epsilon_N^{\text{fe}}} \\
    &\leq O(1)\cdot \Probbig{V(X_\infty, D^{\textup{OL}}_\infty, D^{{{\sysbar{\pi}}^*}}_\infty) > \eta - \epsilon_N^{\text{fe}}} \\
    &= O(\exp(-CN)),
\end{align*}
which will finish the proof. 

In the rest of the proof, we will show \eqref{eq:two-set:thm:interm-goal-1} by invoking \Cref{lem:drift-to-high-prob-bound} with $\overline{\eta} = \eta - \epsilon_N^{\text{fe}}$. 
First, $V(x, D^{\textup{OL}}, D^{{{\sysbar{\pi}}^*}})$ is non-negative and upper bounded by $\lambda_U^{1/2}+\lambda_W^{1/2} + L$, so the condition \eqref{eq:two-set:drift-lem:bounded} holds. To show the other conditions, we first examine the difference $V(\Sigma_{t+1}) - V(\Sigma_t)$. 
Consider the decomposition 
\begin{align}
    V(\Sigma_{t+1}) - V(\Sigma_t) 
    \label{eq:two-set:thm:set-change-diff-term}
    &= \big(V(X_{t+1}, D^{\textup{OL}}_{t+1}, D^{{{\sysbar{\pi}}^*}}_{t+1}) - V(X_{t+1}, D^{\textup{OL}}_{t}, D^{{{\sysbar{\pi}}^*}}_{t}))  \\
    \label{eq:two-set:thm:state-change-diff-term}
    &\mspace{20mu} + \big(V(X_{t+1}, D^{\textup{OL}}_{t}, D^{{{\sysbar{\pi}}^*}}_{t}) -  V(X_{t}, D^{\textup{OL}}_{t}, D^{{{\sysbar{\pi}}^*}}_{t})\big). 
\end{align}
We call the difference term in RHS of \eqref{eq:two-set:thm:set-change-diff-term} the \emph{set-update term}, and the difference term in \eqref{eq:two-set:thm:state-change-diff-term} the \emph{state-transition term}. 
We bound them separately. 

For the set-update term in \eqref{eq:two-set:thm:set-change-diff-term}, we can derive a bound fully in terms of the sizes of sets, using the Lipschitz continuity of $h_W(x, D)$ and $h_U(x, D)$ with respect to $D$ given in \eqref{eq:hw:lipschitz} of \Cref{lem:hw-hu-properties}:
\begin{align}
    \nonumber
    &\mspace{20mu} V(X_{t+1}, D^{\textup{OL}}_{t+1}, D^{{{\sysbar{\pi}}^*}}_{t+1}) - V(X_{t+1}, D^{\textup{OL}}_{t}, D^{{{\sysbar{\pi}}^*}}_{t})  \\
    \nonumber
    &= h_U(X_{t+1}, D^{\textup{OL}}_{t+1}) - h_U(X_{t+1}, D^{\textup{OL}}_{t}) + h_W(X_{t+1}, D^{{{\sysbar{\pi}}^*}}_{t+1}) - h_W(X_{t+1}, D^{{{\sysbar{\pi}}^*}}_{t}) \\
    \nonumber
    &\mspace{20mu} - L (m(D^{\textup{OL}}_{t+1}) - m(D^{\textup{OL}}_{t})) \\
    \label{eq:two-set:thm:set-update-term-1}
    &\leq 2\lambda_U^{1/2} \big(m(D^{\textup{OL}}_{t+1}\backslash D^{\textup{OL}}_t) + m(D^{\textup{OL}}_t \backslash D^{\textup{OL}}_{t+1})\big) + 2\lambda_W^{1/2} \big(m(D^{{{\sysbar{\pi}}^*}}_{t+1}\backslash D^{{{\sysbar{\pi}}^*}}_t) + m(D^{{{\sysbar{\pi}}^*}}_t \backslash D^{{{\sysbar{\pi}}^*}}_{t+1})\big)\\
    &\mspace{20mu} - L (m(D^{\textup{OL}}_{t+1}\backslash D^{\textup{OL}}_t) - m(D^{\textup{OL}}_{t}\backslash D^{\textup{OL}}_{t+1})).
\end{align}
We can bound $m(D^{{{\sysbar{\pi}}^*}}_{t+1}\backslash D^{{{\sysbar{\pi}}^*}}_t)$ and $m(D^{{{\sysbar{\pi}}^*}}_t \backslash D^{{{\sysbar{\pi}}^*}}_{t+1})$ in the last expression in terms of $D^{\textup{OL}}_{t+1}$ and $D^{\textup{OL}}_t$. 
By definition, $D^{{{\sysbar{\pi}}^*}}_{t+1} \supseteq D^{{{\sysbar{\pi}}^*}}_{t} \backslash D^{\textup{OL}}_{t+1}$, and $D^{{{\sysbar{\pi}}^*}}_t$ is disjoint from $D^{\textup{OL}}_t$, so it is not hard to see that
\begin{equation}
    \label{eq:two-set:thm:set-update-term-2} 
    D^{{{\sysbar{\pi}}^*}}_{t}\backslash D^{{{\sysbar{\pi}}^*}}_{t+1} \subseteq D^{\textup{OL}}_{t+1}\backslash D^{\textup{OL}}_t,  \quad m(D^{{{\sysbar{\pi}}^*}}_{t}\backslash D^{{{\sysbar{\pi}}^*}}_{t+1}) \leq m(D^{\textup{OL}}_{t+1}\backslash D^{\textup{OL}}_t).
\end{equation}
Moreover, by definition $m(D^{{{\sysbar{\pi}}^*}}_t) \geq \beta (1-m(D^{\textup{OL}}_{t})) - 1/N$ and  $m(D^{{{\sysbar{\pi}}^*}}_{t+1}) \leq \beta (1-m(D^{\textup{OL}}_{t+1}))$, so 
\begin{align}
    \nonumber
    m(D^{{{\sysbar{\pi}}^*}}_{t+1}\backslash D^{{{\sysbar{\pi}}^*}}_{t}) &= m(D^{{{\sysbar{\pi}}^*}}_{t}\backslash D^{{{\sysbar{\pi}}^*}}_{t+1}) + m(D^{{{\sysbar{\pi}}^*}}_{t+1}) - m(D^{{{\sysbar{\pi}}^*}}_{t}) \\
    \label{eq:two-set:thm:set-update-term-3} 
    &\leq m(D^{\textup{OL}}_{t+1}\backslash D^{\textup{OL}}_t) - \beta(m(D^{\textup{OL}}_{t+1}) - m(D^{\textup{OL}}_t)) + \frac{1}{N}. 
\end{align}
Plugging \eqref{eq:two-set:thm:set-update-term-2} and \eqref{eq:two-set:thm:set-update-term-3} into \eqref{eq:two-set:thm:set-update-term-1}
and rearranging the terms, we get 
\begin{align}
     V(X_{t+1}, D^{\textup{OL}}_{t+1}, D^{{{\sysbar{\pi}}^*}}_{t+1}) - V(X_{t+1}, D^{\textup{OL}}_{t}, D^{{{\sysbar{\pi}}^*}}_{t}) 
     \label{eq:two-set:thm:set-update-term-4} 
    \leq 4\big(\lambda_U^{1/2} + \lambda_W^{1/2}\big) m(D^{\textup{OL}}_t \backslash D^{\textup{OL}}_{t+1}) + \frac{2\lambda_W^{1/2}}{N}, 
\end{align}
where the terms related to $m(D^{\textup{OL}}_{t+1}\backslash D^{\textup{OL}}_t)$ have been canceled out. 

For the state-transition term in \eqref{eq:two-set:thm:state-change-diff-term}, it follows directly from the definition of $V$ that 
\begin{align}
    \nonumber
     &\mspace{20mu} V(X_{t+1}, D^{\textup{OL}}_{t}, D^{{{\sysbar{\pi}}^*}}_{t}) -  V(X_{t}, D^{\textup{OL}}_{t}, D^{{{\sysbar{\pi}}^*}}_{t})\\
     \label{eq:two-set:thm:state-transition-term-1}
     &\leq \big(h_U(X_{t+1}, D^{\textup{OL}}_t) - h_U(X_{t}, D^{\textup{OL}}_t)\big)+ \big(h_W(X_{t+1}, D^{{{\sysbar{\pi}}^*}}_t) - h_W(X_{t}, D^{{{\sysbar{\pi}}^*}}_t)\big)
\end{align}


Combine the above calculations, we get the following key inequality:
\begin{align}
    \nonumber
    & V(\Sigma_{t+1}) - V(\Sigma_t) \\
    \label{eq:two-set:thm:v-diff-term-1}
    &\leq \big(h_U(X_{t+1}, D^{\textup{OL}}_t) - h_U(X_{t}, D^{\textup{OL}}_t)\big)+ \big(h_W(X_{t+1}, D^{{{\sysbar{\pi}}^*}}_t) - h_W(X_{t}, D^{{{\sysbar{\pi}}^*}}_t)\big)\\
    \label{eq:two-set:thm:v-diff-term-2}
    &\mspace{20mu} + 4\big(\lambda_U^{1/2} + \lambda_W^{1/2}\big) m(D^{\textup{OL}}_t \backslash D^{\textup{OL}}_{t+1}) + \frac{2\lambda_W^{1/2}}{N}. 
\end{align}


Next, we verify the drift condition \eqref{eq:two-set:drift-lem:drift-1} of \Cref{lem:drift-to-high-prob-bound}, restated below: when $V(\Sigma_t)\geq \overline{\eta}$, 
\begin{equation}
     \label{eq:two-set:thm:interm-goal-2}
      \Ebig{V(\Sigma_{t+1}) - V(\Sigma_t)\,\big|\, \Sigma_t} \leq -\gamma + O\Big(\frac{1}{\sqrt{N}}\Big) \quad a.s.,
\end{equation}
for a constant $\gamma > 0$. 
We take expectation in the bound \eqref{eq:two-set:thm:v-diff-term-1}-\eqref{eq:two-set:thm:v-diff-term-2}. Because
$\Eplain{h_U(X_{t+1}, D^{\textup{OL}}_t)\,|\, \Sigma_t} \leq \rho_{u} h_U(X_{t}, D^{\textup{OL}}_t) + O(1/\sqrt{N})$, 
$\Eplain{h_W(X_{t+1}, D^{{{\sysbar{\pi}}^*}}_t)\,|\, \Sigma_t} \leq \rho_{w} h_W(X_{t}, D^{{{\sysbar{\pi}}^*}}_t) + O(1/\sqrt{N})$ (\Cref{lem:hw-hu-properties}), 
$\Eplain{m(D^{\textup{OL}}_t \backslash D^{\textup{OL}}_{t+1}) \,|\, \Sigma_t} = O(1/\sqrt{N})$ (\Cref{lem:two-set:non-shrink}), we get 
\begin{equation}
    \label{eq:two-set:thm:full-drift-term-1}
     \Ebig{V(\Sigma_{t+1}) -  V(\Sigma_t) \,\big|\, \Sigma_t} \leq - \big((1-\rho_{u}) h_U(X_{t}, D^{\textup{OL}}_t) + (1-\rho_{w}) h_W(X_{t}, D^{{{\sysbar{\pi}}^*}}_t)\big) + O\Big(\frac{1}{\sqrt{N}}\Big). 
\end{equation}
To show \eqref{eq:two-set:thm:interm-goal-2}, it remains to lower bound the term $(1-\rho_{u}) h_U(X_{t}, D^{\textup{OL}}_t) + (1-\rho_{w}) h_W(X_{t}, D^{{{\sysbar{\pi}}^*}}_t)$ when $V(\Sigma_t) > \overline{\eta}$. 
We invoke \Cref{lem:two-set:sufficient-coverage} to get
\begin{align}
    \nonumber
    V(\Sigma_t) 
    &\leq  h_U(X_{t}, D^{\textup{OL}}_t) +  h_W(X_{t}, D^{{{\sysbar{\pi}}^*}}_t) + L\bigg( \frac{\lambda_U^{1/2}}{\eta\beta}  h_W(X_t, D^{{{\sysbar{\pi}}^*}}_t) + O\Big(\frac{1}{N}\Big)\bigg) \\
    \label{eq:v-h-bound}
    &= K_{Vh} \cdot \big((1-\rho_{u}) h_U(X_{t}, D^{\textup{OL}}_t) + (1-\rho_{w}) h_W(X_{t}, D^{{{\sysbar{\pi}}^*}}_t)\big) + O\Big(\frac{1}{N}\Big), 
\end{align}
for some positive constant $K_{Vh}$. So $ \Ebig{V(\Sigma_{t+1}) -  V(\Sigma_t) \,\big|\, \Sigma_t} \leq - \overline{\eta} / K_{Vh} + O(1/\sqrt{N})$ when $V(\Sigma_t) > \overline{\eta}$, which implies \eqref{eq:two-set:thm:interm-goal-2}. 


Next, we verify the condition \eqref{eq:two-set:drift-lem:jump-1} of \Cref{lem:drift-to-high-prob-bound}, restated below: when $V(\Sigma_t) > \overline{\eta}$, 
\begin{equation}
     \Ebig{(V(\Sigma_{t+1}) - V(\Sigma_t))^+  \,\big|\, \Sigma_t} = O\Big(\frac{1}{\sqrt{N}}\Big) \quad a.s.
\end{equation}
Again, using the bound in \eqref{eq:two-set:thm:v-diff-term-1}-\eqref{eq:two-set:thm:v-diff-term-2}, we have
\begin{align}
    \nonumber
    & \Ebig{(V(\Sigma_{t+1}) - V(\Sigma_t))^+ \,\big|\, \Sigma_t}\\
    \nonumber
    &\leq \Ebig{\big(h_U(X_{t+1}, D^{\textup{OL}}_t) - h_U(X_{t}, D^{\textup{OL}}_t)\big)^+ \,\big|\, \Sigma_t} + \Ebig{\big(h_W(X_{t+1}, D^{{{\sysbar{\pi}}^*}}_t) - h_W(X_{t}, D^{{{\sysbar{\pi}}^*}}_t)\big)^+ \,\big|\, \Sigma_t} \\
    \nonumber
    &\mspace{20mu} + 4\big(\lambda_U^{1/2} + \lambda_W^{1/2}\big) \Ebig{m(D^{\textup{OL}}_t \backslash D^{\textup{OL}}_{t+1})\,\big|\, \Sigma_t} + \frac{2\lambda_W^{1/2}}{N}. 
\end{align}
Each term on the RHS above is $O(1/\sqrt{N})$: In particular, by \Cref{lem:two-set:non-shrink}. $\E{m(D^{\textup{OL}}_t \backslash D^{\textup{OL}}_{t+1}) \,\big|\, \Sigma_t} = O(m(D^{\textup{OL}}_{t})\exp(-CN m(D^{\textup{OL}}_{t})^2)) = O(1/\sqrt{N})$. 

Finally, we show that when $V(\Sigma_t) \leq \overline{\eta}$, 
\begin{equation}
     \label{eq:two-set:thm:interm-goal-4}
    \Probbig{V(\Sigma_{t+1}) > \rho_1 V(\Sigma_t) + r \,\big|\, \Sigma_t} = O(\exp(-CN)) \quad a.s., 
\end{equation}
where $r = (1-\rho_1)\overline{\eta} / 2$, $\rho_1$ is a constant in $(0,1)$ and $C$ is a positive constant. It is not hard to see that \eqref{eq:two-set:thm:interm-goal-4} implies the conditions \eqref{eq:two-set:drift-lem:jump-2} and \eqref{eq:two-set:drift-lem:jump-3} of \Cref{lem:drift-to-high-prob-bound}.  
We rearrange the bound in \eqref{eq:two-set:thm:v-diff-term-1}-\eqref{eq:two-set:thm:v-diff-term-2} and apply \eqref{eq:v-h-bound} to get 
\begin{align*}
    \nonumber
    & V(\Sigma_{t+1}) - \big(1-\frac{1}{K_{Vh}}\big) V(\Sigma_t) \\
    &\leq \big(h_U(X_{t+1}, D^{\textup{OL}}_t) - \rho_{u} h_U(X_{t}, D^{\textup{OL}}_t)\big)+ \big(h_W(X_{t+1}, D^{{{\sysbar{\pi}}^*}}_t) - \rho_{w}h_W(X_{t}, D^{{{\sysbar{\pi}}^*}}_t)\big)\\
    &\mspace{20mu} + 4\big(\lambda_U^{1/2} + \lambda_W^{1/2}\big) m(D^{\textup{OL}}_t \backslash D^{\textup{OL}}_{t+1}) + O\Big(\frac{1}{N}\Big). 
\end{align*}
For $N$ larger than a certain constant threshold, the $O(1/N)$ term in the last expression is less than $r/4$. 
Applying the union bound and \Cref{lem:hw-hu-properties}, we get
\begin{align*}
    &\mspace{20mu} \ProbBig{V(\Sigma_{t+1}) > \big(1-\frac{1}{K_{Vh}}\big) V(\Sigma_t) + r\,\Big|\, \Sigma_t} \\
    &\leq \Probbig{h_U(X_{t+1}, D^{\textup{OL}}_t) > \rho_{u} h_U(X_{t}, D^{\textup{OL}}_t) + r/4 \,\big|\, \Sigma_t} \\
    &\mspace{20mu} + \Probbig{h_W(X_{t+1}, D^{{{\sysbar{\pi}}^*}}_t) > \rho_{w} h_W(X_{t}, D^{{{\sysbar{\pi}}^*}}_t) + r/4 \,\big|\, \Sigma_t} \\
    &\mspace{20mu} + \Probbig{4\big(\lambda_U^{1/2} + \lambda_W^{1/2}\big) m(D^{\textup{OL}}_t \backslash D^{\textup{OL}}_{t+1})  > r/4 \,\big|\, \Sigma_t} + \indibrac{O(1/N) > r/4} \\
    &\leq O(\exp(-CN)) + O(\exp(-CN m(D^{\textup{OL}}_t))). 
\end{align*}
By \Cref{lem:two-set:sufficient-coverage}, $h_U(X_t, D^{\textup{OL}}_t) \leq V(\Sigma_t) < \overline{\eta} = \eta-\epsilon_N^{\text{fe}}$ implies $m(D^{\textup{OL}}_t) =1$, so $O(\exp(-CN m(D^{\textup{OL}}_t)))$ in the last term equals $O(\exp(-CN))$. 
