    \label{eq:two-set:db-condition-2}
     \sum_{s\neq \tilde{s}} {{\sysbar{\pi}}^*}(0|s) X_t(D^{\textup{OL}}_t, s) &\leq (1-\alpha)m(D^{\textup{OL}}_t) - \frac{|S^{\emptyset}|+1}{N}. 
\end{align}
which allows these arms to follow the Optimal Local Control. 

It remains to show that $A_t(i)$ for $i\notin D^{\textup{OL}}_t \cup D^{{{\sysbar{\pi}}^*}}_t$ can be chosen such that $\sum_{i\in[N]} A_t(i) = \alpha N$, if the arms in $D^{\textup{OL}}_t$ and $D^{{{\sysbar{\pi}}^*}}_t$ follow the Optimal Local Control and the Unconstrained Optimal Control, respectively. 


By the definition of the Optimal Local Control, $\sum_{i\in D^{\textup{OL}}_t} A_t(i) \in \{\lfloor\alpha |D^{\textup{OL}}_t|\rfloor, \lceil\alpha |D^{\textup{OL}}_t|\rceil\}$. 
Because $A_t(i)\in \{0,1\}$ for $i\in D^{{{\sysbar{\pi}}^*}}_t$, we have
\[
    \floor{\alpha |D^{\textup{OL}}_t|} \leq \sum_{i\in D^{\textup{OL}}_t\cup D^{{{\sysbar{\pi}}^*}}_t} A_t(i)\leq \ceil{\alpha |D^{\textup{OL}}_t|} + |D^{{{\sysbar{\pi}}^*}}_t|.
\]
Because we can choose $\sum_{i\notin D^{\textup{OL}}_t\cup D^{{{\sysbar{\pi}}^*}}_t} A_t(i)$ to be anything integer between $0$ and $N - |D^{\textup{OL}}_t| - |D^{{{\sysbar{\pi}}^*}}_t|$ to satisfy the budget constraint, it suffices to show that
\begin{align}
    \label{eq:pf-subroutine-conf:interm-goal-1}
