\end{align}
To show \eqref{eq:pf-subroutine-conf:interm-goal-1}, observe that $|D^{{{\sysbar{\pi}}^*}}_t| = \big\lfloor \beta (N -|D^{\textup{OL}}_{t}|)\big\rfloor \leq (1-\alpha)(N - |D^{\textup{OL}}_t|)$, so 
\begin{equation*}
