        \Ebig{Y_t(\tilde{s},0) \,\big|\, X_t, D^{\textup{OL}}_t = [N], D^{{{\sysbar{\pi}}^*}}_t = \emptyset, } &= 1 - \alpha - \sum_{s\neq \tilde{s}} {{\sysbar{\pi}}^*}(0|s) X_t([N], s). 
    \end{align}

\begin{equation}\label{eq:lp-priority-inst-reward}
        \begin{aligned}
        r^\pi(X_t, [N], \emptyset) 
        &= \sum_{s\neq \tilde{s}, a\in\mathbb{A}} \big(r(s,a) - r(\tilde{s},a)\big) {{\sysbar{\pi}}^*}(a|s) X_t([N],s) \\
        &\mspace{20mu} + \alpha r(\tilde{s},1) + (1-\alpha) r(\tilde{s},0),
        \end{aligned}
    \end{equation}

\begin{equation}\label{eq:bar}
        \lim_{T\to\infty} \frac{1}{T} \sum_{t=0}^{T-1} \big(\E{f(V(\Sigma_{t+1}))} - \E{f(V(\Sigma_{t}))}\big) = 0.
    \end{equation}

\[
        \frac{1}{2}\big(V(\Sigma_{t+1}) - V(\Sigma_t)\big) - (\overline{\eta}/2 - V(\Sigma_t)) = \frac{1}{2}\big(V(\Sigma_{t+1}) + V(\Sigma_t)\big) - \overline{\eta}/2 \geq 0;
    \]

\begin{align}
        \nonumber
         &\mspace{20mu} \Ebig{f(V(\Sigma_{t+1})) \,\big|\, \Sigma_t} - f(V(\Sigma_t)) \\ 
         \nonumber
        &\leq  \Ebig{\big(f(V(\Sigma_{t+1})) - f(V(\Sigma_t))\big) \indibrac{V(\Sigma_{t+1}) > V(\Sigma_t)} \,\big|\, \Sigma_t}  \\
        \nonumber
        &=  \Ebig{\big(V(\Sigma_{t+1}) - V(\Sigma_t)\big)^+ \,\big|\, \Sigma_t} \\
        \label{eq:two-set:drift-lem:interm-3}
        &= O(\exp(-C N)),
    \end{align}

\begin{align}
        \nonumber
         &\mspace{20mu} \Ebig{f(V(\Sigma_{t+1})) \,\big|\, \Sigma_t} - f(V(\Sigma_t)) \\ 
         \nonumber
         &= \Ebig{(V(\Sigma_{t+1})-\overline{\eta}/2)^+ \,\big|\, \Sigma_t} \\
         \nonumber
         &\leq V_{\max} \Probbig{V(\Sigma_{t+1})-\overline{\eta}/2 \,\big|\, \Sigma_t} \\
         \label{eq:two-set:drift-lem:interm-4}
         &= O(\exp(-C' N)),
    \end{align}

\begin{equation*}
        \Ebig{f(V(\Sigma_{t+1}))} - \E{f(V(\Sigma_t))} 
        \leq \Big(-\frac{1}{2}\gamma + O(1/\sqrt{N}) \Big) \Probbig{V(\Sigma_{t}) > \overline{\eta}} + O(\exp(-\min(C, C') N)). 
    \end{equation*}

\begin{equation}
        \label{eq:two-set:drift-lem:interm-5}
        \Probbig{V(\Sigma_{t}) > \overline{\eta}} \leq \frac{1}{\gamma / 2 - O(1/\sqrt{N})}\Big( \Ebig{f(V(\Sigma_{t+1}))} - \E{f(V(\Sigma_t))} + O(\exp(-\min(C, C') N))\Big),
    \end{equation}

\textbf{Proving \eqref{eq:hw:drift} and \eqref{eq:hw:high-prob}}
By the pseudo-contraction properties of $W$-weighted norms given in \Cref{lem:one-step-contraction-W-U}, 
\begin{align*}
    \rho_{w} h_W(X_t, D)  
    &=  \rho_{w} \norm{X_{t}(D) - m(D)\mu^*}_W \\
    &\geq \norm{(X_{t}(D) - m(D)\mu^*)P_{{\sysbar{\pi}}^*} }_W \\
    & = \norm{X_{t}(D)P_{{\sysbar{\pi}}^*} - m(D)\mu^*}_W.
\end{align*}
Consequently,
\begin{align*}
    h_W(X_{t+1}', D) - \rho_{w} h_W(X_t, D)  
    &\leq  \norm{X_{t+1}'(D)- m(D)\mu^*}_W -  \norm{X_{t}(D)P_{{\sysbar{\pi}}^*} - m(D)\mu^*}_W \\
    &\leq  \norm{X_{t+1}'(D)- X_t(D) P_{{{\sysbar{\pi}}^*}}}_W \\
    &\leq \lambda_W^{1/2} \norm{X_{t+1}'(D)- X_t(D) P_{{{\sysbar{\pi}}^*}}}_2 \\
    &\leq \lambda_W^{1/2} \norm{X_{t+1}'(D)- X_t(D) P_{{{\sysbar{\pi}}^*}}}_1.
\end{align*}
Therefore, it suffices to show that 
\begin{align}
    \label{eq:hw:interm-goal-1}
    \Ebig{ \norm{X_{t+1}'(D)- X_t(D) P_{{{\sysbar{\pi}}^*}}}_1 \,\big|\, X_t} 
    &= O(1/\sqrt{N}) \quad a.s.  \\
    \label{eq:hw:interm-goal-2}
    \Prob{\norm{X_{t+1}'(D)- X_t(D) P_{{{\sysbar{\pi}}^*}}}_1 > r \,\big|\, X_t} 
    &= O(\exp(-C\lambda_W N r^2))   \quad a.s. \quad \forall r\geq 0.
\end{align}



To show \eqref{eq:hw:interm-goal-1} and \eqref{eq:hw:interm-goal-2}, we examine the distribution of $\normbig{X_{t+1}'(D)- X_t(D) P_{{{\sysbar{\pi}}^*}}}_1$ given $X_t$. 
Note that by \Cref{lem:pibs-transition}, $\Eplain{X_{t+1}'(D) \,|\, X_t} = X_t(D) P_{{{\sysbar{\pi}}^*}}$. 
\begin{align}
    \nonumber
     \normbig{X_{t+1}'(D)- X_t(D) P_{{{\sysbar{\pi}}^*}}}_1
     &= \normbig{X_{t+1}'(D) - \E{X_{t+1}'(D) \,|\, X_t} }_1   \\
     \label{eq:hw:interm-3}
     &\leq \normbig{X_{t+1}'(D) - \E{X_{t+1}'(D) \,|\, X_t, (A_t(i))_{i\in D}} }_1 \\
     \label{eq:hw:interm-4}
     &\mspace{20mu}  +  \normbig{ \E{X_{t+1}'(D) \,|\, X_t, (A_t(i))_{i\in D}} - \E{X_{t+1}'(D) \,|\, X_t} }_1.
\end{align}

We first derive an expectation bound and a high-probability bound for \eqref{eq:hw:interm-3}. 
Note that for each $s\in\mathbb{S}$,
\begin{align*}
    X_{t+1}'(D, s) = \frac{1}{N} \sum_{i\in D} \indibrac{S_{t+1}'(i) = s},
\end{align*}
where $S_{t+1}'(i)$ denote the state of arm $i$ at time $t+1$ if the arms in $D$ follow the Unconstrained Optimal Control at time $t$.
Given $X_t$ and $(A_t(i))_{i\in D}$, $\indibrac{S_{t+1}'(i) = s}$ for $i\in D$ are independent Bernoulli random variables, each with mean $P(S_t(i), A_t(i), s)$. 
By Cauchy-Schwartz, 
\begin{align}
    \nonumber
    &\mspace{20mu} \EBig{\absBig{ X_{t+1}'(D, s) - \Eplain{X_{t+1}'(D, s) \,|\, X_t, (A_t(i))_{i\in D}}} \,\Big|\, X_t, (A_t(i))_{i\in D}}  \\
    \nonumber
    &\leq  \Var{X_{t+1}'(D, s) \,\Big|\, X_t, (A_t(i))_{i\in D}}^{1/2} \\
    \nonumber
    &= \frac{1}{N} \left(\sum_{i\in D} \Var{\indibrac{S_{t+1}'(i) = s}, \,\Big|\, X_t, (A_t(i))_{i\in D}} \right)^2 \\
    \nonumber
    &\leq \frac{1}{\sqrt{N}}. 
\end{align}
By Hoeffding inequality, for all $r\geq 0$, 
\begin{align}
    \nonumber
    \ProbBig{\absBig{ X_{t+1}'(D, s) - \Eplain{X_{t+1}'(D, s) \,|\, X_t, (A_t(i))_{i\in D}}} > r \,\Big|\, X_t, (A_t(i))_{i\in D}} \leq 2\exp\big(-2N r^2\big). 
\end{align}
Therefore, summing over all $s\in\mathbb{S}$ and taking expectations over $(A_t(i))_{i\in D}$, we get
\begin{align}
    \label{eq:hw:interm-5}
     \EBig{\normBig{ X_{t+1}'(D, s) - \Eplain{X_{t+1}'(D, s) \,|\, X_t, (A_t(i))_{i\in D}}}_1 \,\Big|\, X_t} &\leq \frac{|\mathbb{S}|}{\sqrt{N}} \\
     \label{eq:hw:interm-6}
     \ProbBig{\normBig{ X_{t+1}'(D, s) - \Eplain{X_{t+1}'(D, s) \,|\, X_t, (A_t(i))_{i\in D}}}_1 > r \,\Big|\, X_t} &\leq 2|\mathbb{S}|\exp\Big(-\frac{2N r^2}{|\mathbb{S}|^2}\Big),
\end{align}
where \eqref{eq:hw:interm-6} comes from applying a union bound. 

Next, we bound the term in \eqref{eq:hw:interm-4}. 
For any $s\in\mathbb{S}$, we have
\begin{align*}
    \E{X_{t+1}'(D, s) \,|\, X_t, (A_t(i))_{i\in D}} &= \sum_{s'\in\mathbb{S}, a\in\mathbb{A}} \Gamma_t(s',a) P(s', a, s)  \\
    \E{X_{t+1}'(D, s) \,|\, X_t} 
    &= \sum_{s'\in\mathbb{S}, a\in\mathbb{A}} {{\sysbar{\pi}}^*}(a|s) X_t(D, s') P(s', a, s), 
\end{align*}
where $N\cdot\Gamma_t(s,a)$ is the number of arms in $D$ with state $s$ taking action $a$ at time $t$. By the definition of the Unconstrained Optimal Control (\Cref{alg:follow-pibs}), 
\[
  \Gamma_t(s',1) \in \{\ceil{N{{\sysbar{\pi}}^*}(1|s') X_t(D, s')}/N, \floor{N{{\sysbar{\pi}}^*}(1|s') X_t(D, s')}/N \},
\]
and $\Gamma_t(s,0) = X_t(D, s) - \Gamma_t(s,1)$. 
Consequently, 
\begin{align}
    \nonumber
    &\mspace{20mu} \absbig{\E{X_{t+1}'(D, s) \,|\, X_t, (A_t(i))_{i\in D}} - \E{X_{t+1}'(D, s) \,|\, X_t} }  \\
    \nonumber
    &\leq \sum_{s'\in\mathbb{S}, a\in\mathbb{A}} \abs{{{\sysbar{\pi}}^*}(a|s') X_t(D, s')  -  \Gamma_t(s',a)} P(s', a, s) \\
    \label{eq:hw:interm-7}
    &\leq \frac{1}{N} \sum_{s'\in\mathbb{S}, a\in\mathbb{A}} P(s', a, s) \quad a.s. 
\end{align}
Summing over all $s\in\mathbb{S}$ in \eqref{eq:hw:interm-7}, we get 
\begin{align}
    \label{eq:hw:interm-8}
    \normbig{\E{X_{t+1}'(D, s) \,|\, X_t, (A_t(i))_{i\in D}} - \E{X_{t+1}'(D, s) \,|\, X_t}}_1 
    &\leq \frac{2|\mathbb{S}|}{N} \quad a.s.
\end{align}

Combining the above calculations, we get 
\begin{align}
    \nonumber
    &\mspace{20mu} \Ebig{ \norm{X_{t+1}'(D)- X_t(D) P_{{{\sysbar{\pi}}^*}}}_1 \,\big|\, X_t} \\
    \nonumber
    &\leq   \Ebig{ \norm{X_{t+1}'(D) - \E{X_{t+1}'(D, s) \,|\, X_t, (A_t(i))_{i\in D}}}_1 \,\big|\, X_t}  \\
    \nonumber
    &\mspace{20mu} +  \Ebig{\normbig{\E{X_{t+1}'(D, s) \,|\, X_t, (A_t(i))_{i\in D}} - \E{X_{t+1}'(D, s) \,|\, X_t}}_1 \,\big|\, X_t}  \\
    &\leq \frac{1}{\sqrt{N}} + \frac{2|\mathbb{S}|}{N},
\end{align}
which implies \eqref{eq:hw:interm-goal-1}. 
We also have that for any $r\geq 2|\mathbb{S}| / N$, 
\begin{align}
    \nonumber
    &\mspace{20mu} \Prob{\norm{X_{t+1}'(D)- X_t(D) P_{{{\sysbar{\pi}}^*}}}_1 > r \,\big|\, X_t} \\ 
    \nonumber
    &\leq  \Probbig{ \norm{X_{t+1}'(D) - \E{X_{t+1}'(D, s) \,|\, X_t, (A_t(i))_{i\in D}}}_1 > r - \frac{2|\mathbb{S}|}{N} \,\big|\, X_t} \\
    \nonumber
    &\leq 2|\mathbb{S}| \exp\Big(-\frac{2N (r-2|\mathbb{S}|/N)^2}{|\mathbb{S}|^2}\Big) \\
    \label{eq:hw:interm-9}
    &\leq 2|\mathbb{S}| \exp\Big(-\frac{N r^2}{|\mathbb{S}|^2} + \frac{8}{N}\Big)
\end{align}
where we use the fact that $(r - 2|\mathbb{S}|/N)^2 \geq r^2 / 2 - (2|\mathbb{S}|/N)^2$ in the \eqref{eq:hw:interm-9}.  
Note that the above upper bound also holds for $r< 2|\mathbb{S}| / N$ because the term in \eqref{eq:hw:interm-9} is greater than $1$ for $r < 2|\mathbb{S}| / N$. Because $\exp(8/N) = O(1)$, we have proved \eqref{eq:hw:interm-goal-2}:
\[
     \Prob{\norm{X_{t+1}'(D)- X_t(D) P_{{{\sysbar{\pi}}^*}}}_1 > r \,\big|\, X_t} = O(\exp(-C\lambda_W Nr^2)),
\]
where $C = 1/ (\lambda_W |\mathbb{S}|^2)$. This finishes the proof that
\begin{align}
    \tag{\ref{eq:hw:drift}}
    \Ebig{(h_W(X_{t+1}', D) - \rho_{w} h_W(X_t, D))^+ \,\big|\, X_t} &= O(1/\sqrt{N}) \quad a.s. \\
    \tag{\ref{eq:hw:high-prob}}
    \Probbig{h_W(X_{t+1}', D) > \rho_{w} h_W(X_t, D) + r   \,\big|\, X_t} &= O(\exp(-C N r^2)) \quad a.s. \quad \forall r \geq 0.
\end{align}

\textbf{Proving the analogs of \eqref{eq:hw:drift} and \eqref{eq:hw:high-prob} for $h_U$.}
Now let $X_{t+1}'$ denote the system at time $t+1$ given that the arms in $D$ follow the $\textup{Optimal Local Control}$ at time $t$. 
The proof is almost verbatim: We first show 
\begin{align}
    \label{eq:hu:interm-1}
     \EBig{\normBig{ X_{t+1}'(D, s) - \Eplain{X_{t+1}'(D, s) \,|\, X_t, (A_t(i))_{i\in D}}}_1 \,\Big|\, X_t} &\leq \frac{|\mathbb{S}|}{\sqrt{N}} \\
     \label{eq:hu:interm-2}
     \ProbBig{\normBig{ X_{t+1}'(D, s) - \Eplain{X_{t+1}'(D, s) \,|\, X_t, (A_t(i))_{i\in D}}}_1 > r \,\Big|\, X_t} &\leq 2|\mathbb{S}|\exp\Big(-\frac{2N r^2}{|\mathbb{S}|^2}\Big),
\end{align}
using identical arguments. Then we can show that
\begin{align}
    \label{eq:hu:interm-3}
    \normbig{\E{X_{t+1}'(D, s) \,|\, X_t, (A_t(i))_{i\in D}} - \E{X_{t+1}'(D, s) \,|\, X_t}}_1 
    &\leq \frac{4|\mathbb{S}|}{N} \quad a.s.,
\end{align}
using the fact that under Optimal Local Control (\Cref{alg:follow-lp-priority}), for all $s'\in\mathbb{S}$ and $a\in\mathbb{A}$, 
\begin{align*}
    \abs{{{\sysbar{\pi}}^*}(a|s') X_t(D, s')  -  \Gamma_t(s',a)} &\leq \frac{1}{N} \quad a.s. \quad \forall s'\neq \tilde{s} \\
    \abs{{{\sysbar{\pi}}^*}(a|\tilde{s}) X_t(D, \tilde{s})  -  \Gamma_t(\tilde{s},a)} &\leq \frac{|\mathbb{S}|}{N} \quad a.s. 
\end{align*}
Finally, we combine \eqref{eq:hu:interm-1},  \eqref{eq:hu:interm-2} and \eqref{eq:hu:interm-3} to get that under $h_U$, 
\begin{align}
    \label{eq:hu:drift}
    \Ebig{(h_U(X_{t+1}', D) - \rho_{u} h_U(X_t, D))^+ \,\big|\, X_t} &= O(1/\sqrt{N}) \quad a.s. \\
    \label{eq:hu:high-prob}
    \Probbig{h_U(X_{t+1}', D) > \rho_{u} h_U(X_t, D) + r   \,\big|\, X_t} &= O(\exp(-C_U N r^2)) \quad a.s. \quad \forall r \geq 0,
\end{align}
for some constant $C_U > 0$. 

