    \end{equation}
    where $\epsilon_0$ is a positive constant; $d_{\textup{IC}}$ is a function of state-action distribution given by 
    \[
        d_{\textup{IC}}(y) = \sum\nolimits_{s\in S^+} y(s,0)+ \sum\nolimits_{s\in S^-}y(s,1),
    \]
    where $S^+ = \{s\in\mathbb{S}\colon y^*(s,1) > 0, y(s,0) = 0\}$, $S^- = \{s\in\mathbb{S}\colon y^*(s,1) = 0, y^*(s,0) > 0\}$.

\begin{equation}
        R^{\textup{rel}} - R(\pi, \ve{S}_0) \geq \epsilon_0 \lim_{T\to\infty} \frac{1}{T} \sum\nolimits_{t=0}^{T-1} \Ebig{d_{\textup{IC}}(Y_t^{\pi})},
    \end{equation}

We first investigate the dual of \eqref{eq:lp-single}, whose properties help us prove the lemma: 
\begin{align}
    \tag{Dual-LP}\label{eq:lp-dual} \underset{\lambda, \mu, \{f(s)\}_{s\in\mathbb{S}}}{\text{minimize}} &  \mu \\
    \text{subject to}\mspace{12mu}
    \label{eq:dual-lp-constraint}
    &  r(s,a) +  (\alpha - \indibrac{a=1}) \lambda - \mu  + \sum_{s'} P(s,a,s')f(s') \leq f(s)  \quad \forall s\in\mathbb{S}, a\in\mathbb{A} \\
    \nonumber
    & \lambda, \mu, f(s) \in \mathbb{R} \quad \forall s\in\mathbb{S}
\end{align}
Note that the primal problem \eqref{eq:lp-single} is always feasible and bounded, so \eqref{eq:lp-dual} is also feasible and bounded. 
By strong duality of linear programs, the optimal value of the dual problem is $\mu^* = R^{\textup{rel}}$. 
Moreover, there always exists an optimal solution of the dual problem $(\lambda^*, f^*, \mu^*)$ that satisfies strict complementarity with the unique primal optimal solution $y^*$ \citep{GolTuc_56_strict_cs}: 
\begin{equation}
    \label{eq:c-s}
    r(s,a) - \lambda^* \indibrac{a=1} + \lambda^* \alpha - \mu  + \sum_{s'} P(s,a,s')f^*(s') - f^*(s) = 0 \quad \text{ iff } \quad y^*(s,a) = 0.
\end{equation}
Let $r_{\lambda^*}(s,a) = r(s,a) -  \lambda^* \indibrac{a=1} + \lambda^* \alpha$. 
By \eqref{eq:c-s} and the definition of $S^+$ and $S^-$, 
there exists a constant $\epsilon_0 > 0$ such that 
\begin{align}
    \label{eq:lb:scs-1}
     r_{\lambda^*}(s, 0) - R^{\textup{rel}} + \sum_{s'} P(s,0,s')f^*(s') &\leq f^*(s) - \epsilon_0   \quad \forall s\in S^+ \\
    \label{eq:lb:scs-2}
      r_{\lambda^*}(s, 1) - R^{\textup{rel}} + \sum_{s'} P(s,1,s')f^*(s') &\leq f^*(s) - \epsilon_0 \quad \forall s\in S^-.
\end{align} 
Define the function $Q^*\colon \mathbb{S}\times \mathbb{A} \to \mathbb{R}$ as
\[
    Q^*(s,a) = r_{\lambda^*}(s,a) - R^{\textup{rel}} + \sum_{s'} P(s,a,s')f^*(s').
\]
Then \eqref{eq:dual-lp-constraint} implies that $f^*(s) \geq Q^*(s,a)$ for any $s\in\mathbb{S},a\in\mathbb{A}$; 
\eqref{eq:lb:scs-1} and \eqref{eq:lb:scs-2} imply that $Q^*(s,1) - Q^*(s,0)$ is at least $\epsilon_0$ for $s\in S^+$ and at most $-\epsilon_0$ for $s\in S^-$. 

Now, we are ready to bound $R^{\textup{rel}} - R(\pi, \ve{S}_0)$: for any policy $\pi$ and initial state vector $\ve{S}_0$,
\begin{align}
    \nonumber
    &R^{\textup{rel}} - R(\pi, \ve{S}_0)\\
    \nonumber 
    &=  \EBig{R^{\textup{rel}} - \frac{1}{N} \sum_{i\in[N]} r_{\lambda^*}(S_\infty(i), A_\infty(i))} \\
    \nonumber
    &= \frac{1}{N} \sum_{i\in[N]} \EBig{R^{\textup{rel}} - r_{\lambda^*}(S_\infty(i), A_\infty(i))} \\
    \label{eq:lb:apply-rate-conservation}
    &=  \frac{1}{N}\sum_{i\in[N]} \EBig{R^{\textup{rel}} -  r_{\lambda^*}(S_\infty(i), A_\infty(i)) - \sum_{s'\in\mathbb{S}}P(S_\infty(i),A_\infty(i),s')f^*(s') + f^*(S_\infty(i))} \\
    \nonumber
    &= \frac{1}{N}\sum_{i\in[N]} \EBig{-Q^*(S_\infty(i), A_\infty(i)) + f^*(S_\infty(i))}\\
    \label{eq:lb:apply-action-gap}
    &\geq  \frac{1}{N}\sum_{i\in[N]} \epsilon_0 \EBig{\indibrac{S_\infty(i)\in S^+, A_\infty(i) = 0} + \indibrac{S_\infty(i)\in S^-, A_\infty(i) = 1}} \\
