Let $D_t$ be the set given in \Cref{lem:exist-subset-lp-priority}. By the definition of $h_{+}$ and the fact that $m(D_t) \geq 1-2d_{\textup{IC}}(Y_t) - 1/N$, we have
\begin{align}
    \nonumber
    &\mspace{23mu} \Ebig{h_{+}(X_{t+1}, [N]) \,\big|\, X_t, \ve{A}_t} - h_{+}(X_t, [N])  \\
    \label{eq:pf-hus-drift:interm-0}
    &\geq  \Ebig{h_{+}(X_{t+1}, D_t)  \,\big|\, X_t, \ve{A}_t} - h_{+}(X_t, D_t) - 4\lambda_{+}^{1/2} (1-m(D_t))  \\
    \nonumber
    &\geq  \Ebig{h_{+}(X_{t+1}, D_t)  \,\big|\, X_t, \ve{A}_t} - h_{+}(X_t, D_t) - 8 \lambda_{+}^{1/2} d_{\textup{IC}}(Y_t) / \beta - 4\lambda_{+}^{1/2} /(\beta N). 
\end{align}
Note that \eqref{eq:pf-hus-drift:interm-0} uses the definition of $h_{+}$ and the fact that $\norm{v}_{U_{+}} \leq \lambda_{+}^{1/2} \norm{v}_{1}$. 

We first consider the case with $h_{+}(X_t, D_t) > K_1 / \sqrt{N}$. We have 
\begin{align}
    \nonumber
     \Ebig{h_{+}(X_{t+1}, D_t) \,\big|\, \,\big|\, X_t, \ve{A}_t}
    &= \Ebig{\norm{X_{t+1}(D_t) - m(D_t)\mu^*}_{U_{+}} \,\big|\, X_t, \ve{A}_t} \\
    \label{eq:pf-hus-drift:interm-1}
    &\geq \normbig{\Ebig{X_{t+1}(D_t) - m(D_t)\mu^* \,\big|\, X_t, \ve{A}_t}}_{U_{+}} \\
    \label{eq:pf-hus-drift:interm-2}
    &\geq  \normbig{\big(X_{t}(D_t) - m(D_t)\mu^*\big)\Phi}_{U_{+}}  - 2\lambda_{+}^{1/2}/N, 
\end{align}
where \eqref{eq:pf-hus-drift:interm-1} uses Jensen's inequality; 
\eqref{eq:pf-hus-drift:interm-2} invokes \Cref{lem:exist-subset-lp-priority} and the fact that $\norm{v}_{U_{+}} \leq \lambda_{+}^{1/2} \norm{v}_{1}$ for any $v\in\mathbb{R}^{|\mathbb{S}|}$. 
By \Cref{lem:uus-ust-properties}, we have 
\begin{equation*}
    \normplain{v\Phi}_{U_{+}} \geq (1 + \epsilon_1) \normplain{v}_{U_{+}}. 
\end{equation*}
Letting $v = X_{t}(D_t) - m(D_t)\mu^*$, combined with \eqref{eq:pf-hus-drift:interm-2}, we get 
\begin{align*}
     \Ebig{h_{+}(X_{t+1}, D_t) \,\big|\, \,\big|\, X_t, \ve{A}_t} 
     &\geq
     (1+\epsilon_1) h_{+}(X_t, D_t) - \frac{2\lambda_{+}^{1/2}}{N} \\
     &\geq h_{+}(X_t, D_t) + \frac{\epsilon_1 K_1}{\sqrt{N}} - \frac{2\lambda_{+}^{1/2}}{N},
\end{align*}
which implies that 
\begin{equation}
    \label{eq:pf-hus-drift:goal-1}
    \Ebig{h_{+}(X_{t+1}, [N]) \,\big|\, \,\big|\, X_t, \ve{A}_t} - h_{+}(X_t, [N]) \geq \frac{\epsilon_1 K_1}{\sqrt{N}} - \frac{6\lambda_{+}^{1/2}}{\beta N} -  \frac{8 \lambda_{+}^{1/2} d_{\textup{IC}}(Y_t)}{\beta}. 
\end{equation}

Next, we consider the case of $h_{+}(X_t, D_t) \leq K_1 / \sqrt{N}$: 
\begin{align}
    \nonumber
    &\mspace{23mu} \Ebig{h_{+}(X_{t+1}, D_t) \,\big|\, \,\big|\, X_t, \ve{A}_t}  \\
    \nonumber
    &=  \Ebig{\norm{X_{t+1}(D_t) - m(D_t) \mu^*}_{U_{+}}  \,\big|\, X_t, \ve{A}_t} \\
    \nonumber
    &\geq \Ebig{\norm{X_{t+1}(D_t) - m(D_t) \mu^* - (X_t(D_t)-m(D_t) \mu^*)\Phi}_{U_{+}}  \,\big|\, X_t, \ve{A}_t} - \normbig{\big(X_t(D_t) - m(D_t)\mu^*\big)\Phi}_{U_{+}} \\
    \label{eq:pf-hus-drift:interm-3}
    &\geq \Ebig{\norm{X_{t+1}(D_t) - m(D_t) \mu^* - (X_t(D_t) - m(D_t)\mu^*)\Phi}_{U_{+}}  \,\big|\, X_t, \ve{A}_t} - (1+\epsilon_2) h_{+}(X_t, D_t), 
\end{align}
where \eqref{eq:pf-hus-drift:interm-3} uses the fact that $\normplain{v \Phi}_{U_{+}} \leq (1+\epsilon_2) \normplain{v}_{U_{+}}$ for all $v\in \mathbb{R}^{|\mathbb{S}|}$, proved in \Cref{lem:uus-ust-properties}. 
We plan to invoke Property \ref{assump:orthogonal-noise} of regular unstable RBs to bound the first term in \eqref{eq:pf-hus-drift:interm-3}. 
Let $X_{t+1}'(D_t)$ be the state distribution at time $t+1$ when the arms in $D_t$ follow $\textup{Optimal Local Control}$. By \Cref{lem:exist-subset-lp-priority}, there exists a coupling such that $\norm{X_{t+1}'(D_t) - X_{t+1}(D_t)}_1 \leq 2/N$ almost surely, so
\begin{align}
    \nonumber
    &\mspace{23mu} \Ebig{\norm{X_{t+1}(D_t) - m(D_t) \mu^* - (X_t(D_t) - m(D_t)\mu^*)\Phi}_{U_{+}}  \,\big|\, X_t, \ve{A}_t} \\
    \label{eq:pf-hus-drift:interm-4}
    &\geq \Ebig{\norm{X_{t+1}'(D_t) - m(D_t) \mu^* - (X_t(D_t) - m(D_t)\mu^*)\Phi}_{U_{+}}  \,\big|\, X_t, \ve{A}_t} - \frac{2\lambda_{+}^{1/2}}{N}.
\end{align}
Let $\xi^\top$ be the right eigenvector of $U_{+}$ corresponding to the eigenvalue $\lambda_{+}$, with norm $\norm{\xi}_2 = 1$. 
Because $U_{+}$ is positive semidefinite, $U_{+} \geq \lambda_{+}\xi^\top \xi$, so 
\[
    \norm{v}_{U_{+}} \geq \sqrt{\lambda_{+} v\xi^\top \xi v^\top} = \lambda_{+}^{1/2} \absplain{v\xi^\top},
\]
for any $v\in \mathbb{R}^{|\mathbb{S}|}$. 
Moreover, we argue that $\xi$ satisfies the conditions in Property \ref{assump:orthogonal-noise} of regular unstable RBs: the column space of $U_{+}$ is a subspace of the column space of $\Phi$. Because $\mu^* \Phi = 0$, we have $\mu^* U_{+} = 0$, thus $\mu^* \xi^\top = \lambda_{+}^{-1} \mu^* U_{+} \xi^\top = 0$. 
Therefore, by Property \ref{assump:orthogonal-noise} of regular unstable RBs,
\begin{align}
    \nonumber
    &\mspace{23mu} \Ebig{\norm{X_{t+1}'(D_t) - m(D_t) \mu^* - (X_t(D_t) - m(D_t)\mu^*)\Phi}_{U_{+}}  \,\big|\, X_t, \ve{A}_t} \\
    \nonumber
    &\geq \lambda_{+}^{1/2} \Ebig{\absbig{\big(X_{t+1}'(D_t) - m(D_t) \mu^* - (X_t(D_t) - m(D_t)\mu^*)\Phi\big)\xi^\top}  \,\big|\, X_t, \ve{A}_t} \\
    \label{eq:pf-hus-drift:interm-5}
    &\geq \frac{\lambda_{+}^{1/2}K_{\textup{noise}}}{\sqrt{N}} \indibracbig{\norm{X_t(D_t) - m(D_t)\mu^*}_1 \leq m(D_t) \eta'}.
\end{align}
Combining  \eqref{eq:pf-hus-drift:interm-3},  \eqref{eq:pf-hus-drift:interm-4} and \eqref{eq:pf-hus-drift:interm-5}, we get 
\begin{align}
    \nonumber
    &\mspace{23mu} \Ebig{h_{+}(X_{t+1}, D_t) \,\big|\, \,\big|\, X_t, \ve{A}_t} - h_{+}(X_t, D_t)  \\
    \nonumber
    &\geq \frac{\lambda_{+}^{1/2}K_{\textup{noise}}}{\sqrt{N}} \indibracbig{\norm{X_t(D_t) - m(D_t)\mu^*}_1 \leq m(D_t) \eta'} -  (2+\epsilon_2)h_{+}(X_t, D_t) - \frac{2\lambda_{+}^{1/2}}{N} \\
    \nonumber
    &\geq \frac{\lambda_{+}^{1/2}K_{\textup{noise}}}{\sqrt{N}} \indibracbig{\norm{X_t(D_t) - m(D_t)\mu^*}_1 \leq m(D_t) \eta'} -  \frac{(2+\epsilon_2)K_1}{\sqrt{N}} - \frac{2\lambda_{+}^{1/2}}{N}.
\end{align}
Therefore, when $h_{+}(X_t, D_t) \leq K_1 / \sqrt{N}$,
\begin{align}
    \nonumber
     &\mspace{23mu} \Ebig{h_{+}(X_{t+1}, [N]) \,\big|\, \,\big|\, X_t, \ve{A}_t} - h_{+}(X_t, [N]) \\
     \label{eq:pf-hus-drift:goal-2}
     &\geq \frac{\lambda_{+}^{1/2}K_{\textup{noise}}}{\sqrt{N}} \indibracbig{\norm{X_t(D_t) - m(D_t)\mu^*}_1 \leq m(D_t) \eta'} -  \frac{(2+\epsilon_2)K_1}{\sqrt{N}} - \frac{6\lambda_{+}^{1/2}}{\beta N} - \frac{8 \lambda_{+}^{1/2} d_{\textup{IC}}(Y_t)}{\beta}.
\end{align}

Summarizing the bounds \eqref{eq:pf-hus-drift:goal-1} and \eqref{eq:pf-hus-drift:goal-2} and substituting $K_1 = \lambda_{+}^{1/2} K_{\textup{noise}} / (2+\epsilon_1+\epsilon_2)$ in the bounds, we get
\begin{itemize}[leftmargin=1em]
    \item When $h_{+}(X_t, D_t) > K_1 / \sqrt{N}$ or $\norm{X_t(D_t) - m(D_t)\mu^*}_1 \leq m(D_t) \eta'$, we have 
    \begin{equation}
        \label{eq:pf-hus-drift:case-1-2}
         \Ebig{h_{+}(X_{t+1}, [N]) \,\big|\, \,\big|\, X_t, \ve{A}_t} - h_{+}(X_t, [N]) \geq \frac{\epsilon_1 K_1}{\sqrt{N}} - \frac{6\lambda_{+}^{1/2}}{\beta N} -  \frac{8 \lambda_{+}^{1/2} d_{\textup{IC}}(Y_t)}{\beta}. 
    \end{equation}
    \item When $h_{+}(X_t, D_t) \leq K_1 / \sqrt{N}$ and $\norm{X_t(D_t) - m(D_t)\mu^*}_1 > m(D_t) \eta'$, we have
    \begin{align}
        \Ebig{h_{+}(X_{t+1}, [N]) \,\big|\, \,\big|\, X_t, \ve{A}_t} - h_{+}(X_t, [N]) 
        \label{eq:pf-hus-drift:case-3}
        &\geq -  \frac{(2+\epsilon_2)K_1}{\sqrt{N}} - \frac{6\lambda_{+}^{1/2}}{\beta N} -  \frac{8 \lambda_{+}^{1/2} d_{\textup{IC}}(Y_t)}{\beta}.
    \end{align}
\end{itemize}

Note that the conditions separating the two cases above are in terms of $X_t(D_t)$. To complete the proof, we need to state the conditions in terms of $X_t([N])$ instead, observe that 
