\label{lem:assump-6-helper}
    Consider an RB instance with the single-armed MDP $(\mathbb{S}, \mathbb{A}, P, r)$, where $P(s,a,s') > 0$ for all $s\in\mathbb{S}, a\in\mathbb{A}, s'\in\mathbb{S}$. 
    Then this RB instance satisfies Property \ref{assump:orthogonal-noise} in \Cref{def:regular-unstable}.

Throughout this proof, we fix $X_t$ and $A_t$ and omit them in the conditioning when writing expectations or probabilities. 

Recalling the statement of Property \ref{assump:orthogonal-noise}, it suffices to show that for any $\xi \in \mathbb{R}^{|\mathbb{S}|}$ with $\normplain{\xi}_2 = 1$ and $\mu^* \xi^\top = 0$, 
there exists a constant $K_{\textup{noise}} > 0$ such that 
for any $N$ larger than a constant and any time step $t$, if the local optimal policy is applicable, we have
\begin{equation}
    \label{eq:pf-assumption-6-helper-lemma:goal}
    \Ebig{\absbig{\big(X_{t+1}([N]) - \mu^* - (X_t([N]) - \mu^*)\Phi \big)  \xi^\top } \,\big|\, X_t, \ve{A}_t} \geq \frac{K_{\textup{noise}}}{\sqrt{N}}, 
\end{equation}
where $\ve{A}_t$ follows the Optimal Local Control. 
Note that in this case, the parameter $\eta'$ in Property \ref{assump:orthogonal-noise} of \Cref{def:regular-unstable} could be any positive number such that $\norm{X_t([N]) - \mu^*}_1 \leq \eta'$ guarantees the condition \eqref{eq:lp-priority-condition-1} for applying the Optimal Local Control. 


We first show that for any $\xi \in \mathbb{R}^{|\mathbb{S}|}$ such that $\norm{\xi}_2 = 1$ and $\mu^* \xi^\top = 0$,
\begin{equation}
    \label{eq:xi-max-minus-min}
    \xi_{\max} - \xi_{\min} \geq 1/\sqrt{|\mathbb{S}|}.
\end{equation}
where $\xi_{\max} = \max_{s\in\mathbb{S}} \xi(s)$ and $\xi_{\min} = \min_{s\in\mathbb{S}} \xi(s)$. 
Observe that we must have either $\xi_{\max} \geq 1/\sqrt{|\mathbb{S}|}$ or $\xi_{\min} \geq - 1/\sqrt{|\mathbb{S}|}$, because otherwise $\norm{\xi}_2 < 1$.  
We first show \eqref{eq:xi-max-minus-min} for the case with $\xi_{\max} \geq 1/\sqrt{|\mathbb{S}|}$. In this case, we must have $\xi_{\min} \leq 1/\sqrt{|\mathbb{S}|}$, because otherwise $\norm{\xi}_2 > 1$. 
Let $\mathbbm{1}_{\textup{scaled}} \in \mathbb{R}^{|\mathbb{S}|}$ be the whose entries are all $1/\sqrt{|\mathbb{S}|}$. Then 
\[
    \norm{\xi -\mathbbm{1}_{\textup{scaled}}}_\infty \leq \max\big(\xi_{\max} - 1/\sqrt{|\mathbb{S}|}, 1/\sqrt{|\mathbb{S}|} - \xi_{\min}\big) \leq \xi_{\max} - \xi_{\min}. 
\]
On the other hand, because $\norm{\mu^*}_1 = 1$ and $\mu^* \mathbbm{1}_{\textup{scaled}}^\top = 1/\sqrt{|\mathbb{S}|}$, 
\[
     \norm{\xi - \mathbbm{1}_{\textup{scaled}}}_\infty \geq \mu^* \mathbbm{1}_{\textup{scaled}}^\top - \mu^* \xi^\top = 1/\sqrt{|\mathbb{S}|}. 
\]
Combining the last two inequalities yields \eqref{eq:xi-max-minus-min}. For the case with $\xi_{\min} \leq -1/\sqrt{|\mathbb{S}|}$, \eqref{eq:xi-max-minus-min} can be proved in an analogous way.

To show \eqref{eq:pf-assumption-6-helper-lemma:goal}, we invoke the Paley-Zygmund inequality to get
\begin{align}
    \nonumber
    &\mspace{23mu} \Prob{\big(X_{t+1}([N]) \xi^\top -\Eplain{X_{t+1}([N]) \xi^\top}\big)^2  > \frac{1}{2}\Var{X_{t+1}([N]) \xi^\top}} \\
    \label{eq:pf-assumption-6-helper-lemma:interm-0}
    &\geq \frac{1}{4} \frac{\Var{X_{t+1}([N]) \xi^\top}^2}{\E{\big(X_{t+1}([N]) \xi^\top -\Eplain{X_{t+1}([N]) \xi^\top}\big)^4}}.
\end{align}

Next, we lower bound the second moment of $X_{t+1}([N]) \xi^\top -\Eplain{X_{t+1}([N]) \xi^\top}$ in \eqref{eq:pf-assumption-6-helper-lemma:interm-0}.  
For any timestep $t$, given $X_t, \ve{A}_t$, we have
\begin{align}
    X_{t+1}([N]) \xi^\top
    &= \sum_{s\in\mathbb{S}} X_{t+1}([N], s) \xi(s) \\
    &= \frac{1}{N} \sum_{s\in\mathbb{S}}  \sum_{i\in[N]} \indibrac{\ve{S}_{t+1}(i) = s} \xi(s) \\
    &= \frac{1}{N} \sum_{i\in[N]} \xi(\ve{S}_{t+1}(i)). 
\end{align}
Note that conditioned on $X_t, \ve{A}_t$, $\xi(\ve{S}_{t+1}(i))$ are independent across $i$. Therefore, the variance of $X_{t+1}([N]) \xi^\top$ is given by 
\[
    \Var{X_{t+1}([N]) \xi^\top} = \frac{1}{N^2} \sum_{i\in[N]} \Var{\xi(\ve{S}_{t+1}(i))}.
\]
Because $P(s,a,s') > 0$ for all $s,s'\in\mathbb{S}, a\in\mathbb{A}$, the support of $\ve{S}_{t+1}(i)$ is the whole state space $\mathbb{S}$. Moreover, because $\xi_{\max} - \xi_{\min} > 1/\sqrt{|\mathbb{S}|}$, we have
\begin{align*}
    \Var{\xi(\ve{S}_{t+1}(i))} 
    &\geq \min_{s,a,s'} P(s,a,s') \Big( (\xi_{\max} - \E{\xi(\ve{S}_{t+1}(i))})^2 + (\xi_{\min} - \E{\xi(\ve{S}_{t+1}(i))})^2 \Big) \\
    &\geq \frac{1}{2} \min_{s,a,s'} P(s,a,s')  (\xi_{\max} - \xi_{\min})^2 \\
    &\geq \frac{\min_{s,a,s'} P(s,a,s')}{2|\mathbb{S}|},
\end{align*}
where $\min_{s,a,s'}$ is a shorthand for $\min_{s,s'\in\mathbb{S}, a\in\mathbb{A}}$. 
Therefore, 
\begin{equation}
    \label{eq:pf-assumption-6-helper-lemma:interm-1}
    \Var{X_{t+1}([N]) \xi^\top} \geq \frac{1}{N^2} \sum_{i\in[N]} \Var{\xi(\ve{S}_{t+1}(i))} \geq \frac{\min_{s,a,s'} P(s,a,s')}{2|\mathbb{S}|N}.
\end{equation}

Next, we upper bound the fourth moment of $X_{t+1}([N]) \xi^\top -\Eplain{X_{t+1}([N]) \xi^\top}$. Using the fact that $X_{t+1}([N]) \xi^\top = \sum_{i\in[N]} \xi(\ve{S}_{t+1}(i)) / N$, we get 
\begin{align}
    \nonumber
    &\mspace{23mu} \E{\big(X_{t+1}([N]) \xi^\top -\Eplain{X_{t+1}([N]) \xi^\top}\big)^4} \\
    \nonumber
    &= \frac{1}{N^4} \Big( \sum_{i\in[N]} \E{\big(\xi(\ve{S}_{t+1}(i)) - \E{\xi(\ve{S}_{t+1}(i)}\big)^4}
    + 6 \sum_{1\leq i < j \leq N} \Var{\xi(\ve{S}_{t+1}(i)} \Var{\xi(\ve{S}_{t+1}(j)}
    \Big) \\
    \nonumber
    &\leq \frac{1}{N^4}\Big(N (\xi_{\max} - \xi_{\min})^4 + 6 \frac{N(N-1)}{2} (\xi_{\max} - \xi_{\min})^4 \Big) \\
    \label{eq:pf-assumption-6-helper-lemma:interm-2}
    &\leq \frac{3(\xi_{\max}-\xi_{\min})^4}{N^2}.
\end{align}

Substituting the calculations in \eqref{eq:pf-assumption-6-helper-lemma:interm-1} and \eqref{eq:pf-assumption-6-helper-lemma:interm-2} back to \eqref{eq:pf-assumption-6-helper-lemma:interm-0}, we get
\begin{align}
    \nonumber
    &\mspace{23mu} \Prob{\big(X_{t+1}([N]) \xi^\top -\Eplain{X_{t+1}([N]) \xi^\top}\big)^2  >  \frac{\min_{s,a,s'} P(s,a,s')}{4|\mathbb{S}|N}} \\
    \nonumber
    &\geq \Big(\frac{\min_{s,a,s'} P(s,a,s')}{2|\mathbb{S}|N}\Big)^2  \frac{N^2}{12(\xi_{\max}-\xi_{\min})^4} \\
     \label{eq:pf-assumption-6-helper-lemma:interm-3}
    &= \frac{\min_{s,a,s'} P(s,a,s')^2}{47|\mathbb{S}|^2 (\xi_{\max}-\xi_{\min})^4}. 
\end{align}
Because under the Optimal Local Control, we have $\norm{\Eplain{X_{t+1}([N]) \,|\, X_t, \ve{A}_t} - \Eplain{X_{t+1}([N]) \xi^\top \,|\, X_t}} \leq 2/N$ and $\Eplain{X_{t+1}([N]) \,|\, X_t} = X_t([N]) \Phi$, we can rewrite the bound \eqref{eq:pf-assumption-6-helper-lemma:interm-3} to get
\[
    \Prob{\absbig{\big(X_{t+1}([N]) \xi^\top - X_t([N]) \Phi \big)\xi^\top} >  \frac{\min_{s,a,s'} P(s,a,s')^{1/2}}{2|\mathbb{S}|^{1/2} \sqrt{N}} - \frac{2}{N} } \geq \frac{\min_{s,a,s'} P(s,a,s')^2}{47|\mathbb{S}|^2 (\xi_{\max}-\xi_{\min})^4}.
\]
Therefore, 
\begin{align*}
